import {addressKey} from './domain.js?v=0.24.0';
export const ISSUE_TYPES=['Forgot item','Incorrect item','Damaged / spilled item','Other'];
export function cleanItems(value){if(typeof value==='string')return value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,60).map(name=>({name:name.slice(0,300),quantity:1}));if(!Array.isArray(value))return [];return value.slice(0,60).filter(x=>x&&typeof x.name==='string'&&x.name.trim()).map(x=>({name:x.name.trim().slice(0,300),quantity:Number.isFinite(Number(x.quantity))?Math.min(99,Math.max(1,Math.round(Number(x.quantity)))):1}));}
export const itemsText=items=>cleanItems(items).map(x=>(x.quantity>1?x.quantity+' × ':'')+x.name).join('\n');
export function orderPlaced(value,enteredAt){if(!value)return null;const time=Date.parse(value);if(!Number.isFinite(time)||time>Date.now()+60000||time>Date.parse(enteredAt||new Date().toISOString())+60000)throw Error('Order placed time must be a valid time before the order was added.');return new Date(time).toISOString();}
export function historicalItems(state,address,currentId){const previous=state.deliveries.filter(d=>d.id!==currentId&&!d.recoveryOf&&d.status!=='canceled'&&addressKey(d.address)===addressKey(address));return {cold:previous.some(d=>d.hasColdItems),alcohol:previous.some(d=>d.hasAlcohol)};}
export function reportIssue(state,deliveryId,{type,items,notes,needsFollowUp},at,issueId,recoveryId){const d=state.deliveries.find(x=>x.id===deliveryId);if(!d||!['active','delivered'].includes(d.status))throw Error('Report issues on an active or delivered order.');if(!ISSUE_TYPES.includes(type))throw Error('Choose an issue.');const selected=cleanItems(items),note=String(notes||'').trim().slice(0,2000);if(!selected.length&&!note)throw Error('Select an item or describe the issue.');const shift=state.shifts.find(s=>s.status==='active');if(needsFollowUp&&!shift)throw Error('Start a shift before adding a follow-up delivery.');if(needsFollowUp&&state.deliveries.some(x=>x.recoveryOf===d.id&&!['delivered','canceled'].includes(x.status)))throw Error('This order already has an unfinished follow-up.');d.issues??=[];const issue={id:issueId,type,items:selected,notes:note,reportedAt:at,followUpId:needsFollowUp?recoveryId:null};d.issues.push(issue);if(!needsFollowUp)return issue;const run=state.runs.find(r=>r.status==='active'&&r.shiftId===shift.id&&r.deliveryIds.includes(d.id));const follow={id:recoveryId,shiftId:shift.id,customerId:d.customerId||null,name:d.name,phone:d.phone,address:d.address,ticket:d.ticket,status:'pending',enteredAt:at,recoveryOf:d.id,issueId,items:selected,hasAlcohol:d.hasAlcohol===true,hasColdItems:d.hasColdItems===true,coldItemDetails:selected.length?itemsText(selected):d.coldItemDetails||'Check original order',needsSignature:!!d.hasAlcohol||!!d.needsSignature,notes:`Follow-up: ${type}. ${note}`.trim(),deliveryMode:run?.batchId?'batch':'single',batchId:run?.batchId||null,batchPosition:-1,recoveryPriority:true};state.deliveries.push(follow);if(run){run.deliveryIds.push(follow.id);follow.recoveryRunId=run.id;delete run.completedAt;delete run.completionKind;delete run.completedDeliveryIds;}return issue;}
export function operationalSummary(state,shifts){const ids=new Set(shifts.map(s=>s.id)),orders=state.deliveries.filter(d=>ids.has(d.shiftId)&&!d.recoveryOf&&d.status!=='canceled'),issues=orders.flatMap(d=>d.issues||[]),follow=state.deliveries.filter(d=>ids.has(d.shiftId)&&d.recoveryOf&&d.status!=='canceled'),prep=orders.filter(d=>d.orderPlacedAt&&d.readyAt&&Date.parse(d.readyAt)>=Date.parse(d.orderPlacedAt));return {orders:orders.length,completed:orders.filter(d=>d.status==='delivered').length,issues:issues.length,followUps:follow.length,resolved:follow.filter(d=>d.status==='delivered').length,prepCount:prep.length,prepAverage:prep.length?prep.reduce((n,d)=>n+(Date.parse(d.readyAt)-Date.parse(d.orderPlacedAt))/60000,0)/prep.length:null,types:ISSUE_TYPES.map(type=>({type,count:issues.filter(i=>i.type===type).length})),itemCount:orders.filter(d=>cleanItems(d.items).length).length};}
